// HasRelaySite applies the HasEdge predicate on the "relay_site" edge.
func HasRelaySite() predicate.RelaySiteAnnouncement {
	return predicate.RelaySiteAnnouncement(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RelaySiteTable, RelaySiteColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRelaySiteWith applies the HasEdge predicate on the "relay_site" edge with a given conditions (other predicates).
func HasRelaySiteWith(preds ...predicate.RelaySite) predicate.RelaySiteAnnouncement {
	return predicate.RelaySiteAnnouncement(func(s *sql.Selector) {
		step := newRelaySiteStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelaySiteAnnouncement) predicate.RelaySiteAnnouncement {
	return predicate.RelaySiteAnnouncement(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelaySiteAnnouncement) predicate.RelaySiteAnnouncement {
	return predicate.RelaySiteAnnouncement(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelaySiteAnnouncement) predicate.RelaySiteAnnouncement {
	return predicate.RelaySiteAnnouncement(sql.NotPredicates(p))
}
